sys_script_include.script:
function GenerateStakeholderInvitation(vStakeholder)
{
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var GetUserRecord = x_snc_devtools.GetUserRecord;
	var GetInstanceRecordUrl = x_snc_devtools.GetInstanceRecordUrl;
	var GetStringValue = x_snc_devtools.GetStringValue;


	var grStakeholder = GetStakeholderRecord(vStakeholder);
	if (IsValidRecord(grStakeholder) == false)
	{
		return false;
	}

	var grUser = GetUserRecord(grStakeholder.user);
	if (IsValidRecord(grUser) == false)
	{
		return false;
	}

	var grProcess = GetBusinessProcessRecord(grStakeholder.business_process);
	if (IsValidRecord(grProcess) == false)
	{
		return false;
	}	

	var strUrl = GetInstanceRecordUrl('x_snc_agenticbpc_business_process',grProcess.sys_id);
	var strProcessName = GetStringValue(grProcess.name);

	var strMessage = 'Hello ';
		strMessage += grUser.first_name + ' ';
		strMessage += grUser.last_name + ',\n\n';
		strMessage += 'We kindly ask you to participate in an AI augmented interview regarding process "'+strProcessName+'".\n\n';
		strMessage += 'Please navigate to:\n';
		strMessage += strUrl + '\n';
		strMessage += 'Click on "Start Interview" to start the interview!\n\n';
		strMessage += 'We appreciate your cooperation.!\n';


	return strMessage;
}
